func parseStructFromGoFile(filename string) ([]byte, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	var structBytes []byte
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := scanner.Text()
		if line == "type \"struct\" {\n" {
			break
		} else if !scanner.Scan() && len(structBytes) > 0 {
			structBytes = append(structBytes, '\n')
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}

	// Unmarshal the JSON into a map[string]interface{}
	json.Unmarshal(structBytes, &map[string]interface{}{})
	return json.Marshal(map[string]interface{}{
		"type":      "record",
		"name":      "YourStructName", // Replace with your struct name
		"description": `Your struct description here`,
	})
}

// Main function to process the Go source file and generate the Avro schema
