	filename := os.Args[1]
	structName := os.Args[2]

	avscData, err := parseStructFromGoFile(filename)
	if err != nil {
		fmt.Printf("Error parsing struct: %v\n", err)
		return
	}

	err = ioutil.WriteFile(fmt.Sprintf("%s.avsc", filename), avscData, 0644)
	if err != nil {
		fmt.Printf("Error writing Avro schema: %v\n", err)
		return
	}

	fmt.Println("Avro schema generated successfully at:", fmt.Sprintf("%s.avsc", filename))
